#!/usr/bin/env bash
# Move the results of earlier runs OUT of the project folder, so a new agy (LLM harness) run
# cannot read old designs, memories or transcripts. Nothing is deleted except no_backup/,
# which is regenerated by every simulation. Undo with:  bash restore_past_runs.sh
#
#   bash hide_past_runs.sh          (archive goes to ~/CAD_prj_archive, or set CAD_ARCHIVE=...)
#
# While the data is hidden, git shows these files as deleted: do NOT commit until restored.
set -euo pipefail
cd "$(dirname "$0")"
ARCHIVE="${CAD_ARCHIVE:-$HOME/CAD_prj_archive}"

ITEMS=(harness_runs AGY_RUNS.md solutions output_figs Reference_Designs Milestones_Details
       pvt_robust_v2.log pvt_robust_v3.log run_sweep.sh_output.txt)

if [ -d "$ARCHIVE" ] && [ -n "$(ls -A "$ARCHIVE")" ]; then
  echo "$ARCHIVE is not empty: run restore_past_runs.sh first." >&2; exit 1
fi
mkdir -p "$ARCHIVE"

for p in "${ITEMS[@]}"; do
  if [ -e "$p" ]; then mv "$p" "$ARCHIVE/" && echo "moved  $p"; fi
done

# old generated netlists / simulation outputs: regenerated on every run
rm -rf ./no_backup
mkdir -p no_backup/output_files no_backup/output_netlists
echo "emptied no_backup/"
echo "Past-run data is in $ARCHIVE. Restore after the agy run with: bash restore_past_runs.sh"
